
/* GymSis 10.3 · numeric input hardening */
function gymsibsNumber(value){
  if(value === null || value === undefined) return 0;
  const s=String(value).trim().replace(',','.');
  if(s==='') return 0;
  const n=Number(s);
  return Number.isFinite(n) && n >= 0 ? n : 0;
}


/* GymSis · perfiles */
const GymSis_ARA_ID = '4bea2fa0-438b-4f8c-b287-f909d32ac988';
function gymsibsPlayer(userId){
  if(userId===GymSis_ARA_ID) return 'ara';
  const profile=(typeof data!=='undefined'?data.profiles:[]).find(p=>p.id===userId);
  if(profile?.name) return profile.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'');
  return null;
}
function gymsibsPlayers(){
 const profiles=(data.profiles||[]);
 const order=['ara','andrea'];
 return profiles.map(p=>({id:p.id,name:p.name||'Usuario',key:gymsibsPlayer(p.id),color:p.color||'#8F32FF'})).filter(p=>order.includes(p.key)).sort((a,b)=>order.indexOf(a.key)-order.indexOf(b.key));
}
function gymsibsPlayerByKey(key){return gymsibsPlayers().find(p=>p.key===key)||null;}
function gymsibsPlayerColor(key){return key==='ara'?'#FF168F':key==='andrea'?'#8F32FF':null;}
function gymsibsWeight(value){
  const n=parseFloat(String(value??'').trim().replace(',','.'));
  return Number.isFinite(n)&&n>=0?n:0;
}


