/* GymSis V13.2 splash failsafe: independent from Supabase/app startup. */
(function(){
  const splash=document.getElementById("splash");
  if(!splash) return;
  const key="gymsibs_splash_date";
  const today=new Date().toISOString().slice(0,10);
  try {
    if(localStorage.getItem(key)!==today) localStorage.setItem(key,today);
  } catch(e) {}
  setTimeout(()=>{ splash.classList.add("hide"); },1000);
  setTimeout(()=>{ splash.remove(); },1400);
})();



