async function handleSession(s){session=s;currentUser=s?.user||null;if(!currentUser){loading=false;authScreen();return}if(currentUser.id==='bd71c9fe-a4ae-4ae9-8ab9-5c9e1eb33650'){await sb.auth.signOut();session=null;currentUser=null;loading=false;authScreen('El perfil de Sergio ya no está disponible en GymSis.');return}loading=true;render();try{await loadData();}catch(err){console.error(err);loading=false;authScreen(`No se han podido cargar los datos. ${err?.message||'Recarga la app.'}`);return}loading=false;render();maybeShowMondayDuel()}
async function loadData(){
  if(!window.supabase || !sb) throw new Error('La librería de Supabase no se ha podido cargar.');

  // Cargamos primero SOLO las cuatro tablas que ya existían y que hacen funcionar la app.
  // Natación es opcional: si esa tabla tiene cualquier problema, no debe bloquear GymSis.
  const fetchAllRows=async(table,columns,orders=[])=>{
    const pageSize=1000;let from=0,all=[];
    while(true){
      let q=sb.from(table).select(columns);
      for(const [column,ascending] of orders)q=q.order(column,{ascending});
      const {data:page,error}=await q.range(from,from+pageSize-1);
      if(error)throw error;
      all=all.concat(page||[]);
      if(!page||page.length<pageSize)break;
      from+=pageSize;
    }
    return {data:all,error:null};
  };
  const [p,e,w,st]=await Promise.all([
    fetchAllRows('profiles','id,name,color',[['name',true]]),
    fetchAllRows('exercises','id,name,group_name,icon,active',[['name',true]]),
    fetchAllRows('workouts','id,user_id,exercise_id,date,weight,reps,created_at',[['date',false],['created_at',false]]),
    fetchAllRows('steps','id,user_id,date,steps,created_at',[['date',false]])
  ]);

  const coreErrors=[
    ['profiles',p],['exercises',e],['workouts',w],['steps',st]
  ].filter(([,x])=>x?.error);

  if(coreErrors.length){
    const [table,x]=coreErrors[0];
    console.error('GymSis loadData error:',table,x.error);
    throw new Error(`Error cargando ${table}: ${x.error?.message||x.error?.details||'error desconocido'}`);
  }

  data.profiles=p.data||[];
  currentProfile=data.profiles.find(x=>x.id===currentUser.id)||null;person=gymsibsPlayer(currentUser.id)||'ara';
  if(!currentProfile){
    currentProfile={
      id:currentUser.id,
      name:gymsibsPlayer(currentUser.id)==='ara'?'Ara':'Andrea',
      color:gymsibsPlayerColor(gymsibsPlayer(currentUser.id))
    };
  }
  data.exercises=(e.data||[]).map(x=>({id:x.id,name:x.name,group:x.group_name||'Otros',icon:x.icon||'🏋️',active:x.active!==false}));
  data.records=w.data||[];
  data.steps=st.data||[];

  // Natación no puede impedir que la aplicación arranque.
  try{
    const sw=await fetchAllRows('swimming','id,user_id,date,lengths,created_at',[['date',false]]);
    if(sw.error){
      console.warn('Natación no disponible todavía:',sw.error);
      data.swimming=[];
    }else{
      data.swimming=sw.data||[];
    }
  }catch(err){
    console.warn('Natación no disponible todavía:',err);
    data.swimming=[];
  }
  try{
    const pl=await sb.from('pilates').select('id,user_id,date,classes,created_at').order('date',{ascending:false});
    data.pilates=pl.error?[]:(pl.data||[]);
  }catch(err){data.pilates=[];}
}
function exerciseName(id){return data.exercises.find(x=>x.id===id)?.name||id||'Ejercicio'}
function currentName(){return (currentProfile?.name||selectedLogin||'').toLowerCase()}
function mondayOf(date=new Date()){const d=new Date(date);d.setHours(0,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d}
function isoDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekRange(){const start=mondayOf();const end=new Date(start);end.setDate(end.getDate()+6);return {start:isoDate(start),end:isoDate(end)}}
function weeklyWorkouts(){const r=weekRange();return data.records.filter(x=>x.date>=r.start&&x.date<=r.end)}
function weekRangeFor(date){const start=mondayOf(date);const end=new Date(start);end.setDate(end.getDate()+6);return {start:isoDate(start),end:isoDate(end)};}
function previousWeekRange(){const d=mondayOf();d.setDate(d.getDate()-7);return weekRangeFor(d);}
function isMonday(){return new Date().getDay()===1;}
function weeklyCompetition(range){
 const players=gymsibsPlayers();
 const totals=Object.fromEntries(players.map(p=>[p.key,{...p,wins:0,steps:0,swim:0}]));
 const rows={};
 // Se incluyen ejercicios activos y también los que tengan registros en la semana,
 // aunque se hayan archivado después: el historial nunca debe desaparecer del duelo.
 data.exercises.forEach(e=>rows[e.id]={name:e.name,icon:e.icon||'🏋️',values:Object.fromEntries(players.map(p=>[p.key,0]))});
 const weekRecords=data.records.filter(w=>String(w.date||'').slice(0,10)>=range.start&&String(w.date||'').slice(0,10)<=range.end);
 weekRecords.forEach(w=>{
   const key=gymsibsPlayer(w.user_id);
   if(!key||!totals[key])return;
   if(!rows[w.exercise_id])rows[w.exercise_id]={name:exerciseName(w.exercise_id),icon:'🏋️',values:Object.fromEntries(players.map(p=>[p.key,0]))};
   rows[w.exercise_id].values[key]=Math.max(rows[w.exercise_id].values[key],gymsibsWeight(w.weight));
 });
 data.steps.filter(x=>String(x.date||'').slice(0,10)>=range.start&&String(x.date||'').slice(0,10)<=range.end).forEach(x=>{const k=gymsibsPlayer(x.user_id);if(k&&totals[k])totals[k].steps+=Number(x.steps)||0;});
 data.swimming.filter(x=>String(x.date||'').slice(0,10)>=range.start&&String(x.date||'').slice(0,10)<=range.end).forEach(x=>{const k=gymsibsPlayer(x.user_id);if(k&&totals[k])totals[k].swim+=Math.max(0,Math.floor(Number(x.lengths)||0));});
 const details=[];let ties=0;
 const addResult=(name,icon,type,values,exerciseId=null)=>{
   const active=players.filter(p=>(Number(values[p.key])||0)>0);
   if(!active.length)return;
   // Los ejercicios solo participan si AMBAS personas tienen un peso registrado.
   // Si falta cualquiera de los dos registros, el ejercicio no suma puntos ni XP.
   if(type==='exercise' && (players.length!==2 || active.length!==2))return;
   let winners=[];
   const max=Math.max(...active.map(p=>Number(values[p.key])||0));
   winners=active.filter(p=>(Number(values[p.key])||0)===max).map(p=>p.key);
   if(winners.length===1)totals[winners[0]].wins++;else ties++;
   details.push({name,icon,type,values,winners,active:active.map(p=>p.key),exerciseId,pending:false});
 };
 Object.entries(rows).forEach(([id,x])=>addResult(x.name,x.icon,'exercise',x.values,id));
 addResult('Pasos','👟','steps',Object.fromEntries(players.map(p=>[p.key,totals[p.key].steps])));
 addResult('Natación','🏊','swim',Object.fromEntries(players.map(p=>[p.key,totals[p.key].swim])));
 const ranking=[...players].sort((a,b)=>totals[b.key].wins-totals[a.key].wins);
 const top=ranking[0];
 const overall=ranking.length>1&&totals[top.key].wins===totals[ranking[1].key].wins?'tie':top?.key||'tie';
 return {range,players,totals,rows,details,ties,overall};
}
function formatValue(d){return d.type==='steps'?Number(d).toLocaleString('es-ES'):d.type==='swim'?Number(d).toLocaleString('es-ES')+' largos':gymsibsWeight(d)+' kg';}
function weeklyScore(){const c=weeklyCompetition(weekRange());return {rows:c.rows,ties:c.ties,players:c.players,totals:c.totals}}
function duel(){
 const range=previousWeekRange(),c=weeklyCompetition(range),players=c.players;
 const ranking=[...players].sort((a,b)=>c.totals[b.key].wins-c.totals[a.key].wins);
 const scoreCards=players.map(p=>`<div class="fighter" style="background:${p.color}22;border-color:${p.color}"><small>${esc(p.name.toUpperCase())}</small><b>${c.totals[p.key].wins}</b><small>PUNTOS</small></div>`).join('');
 const rows=c.details.map(d=>{const values=players.map(p=>({k:p.key,v:Number(d.values[p.key])||0,p}));const max=Math.max(...values.map(x=>x.v));const winners=values.filter(x=>x.v===max&&x.v>0).map(x=>x.p.name);const result=winners.length===1?'🏆 GANA '+esc(winners[0].toUpperCase()):'🤝 EMPATE';return `<div class="duel-v11-card"><h3>${d.icon} ${esc(d.name.toUpperCase())}</h3>${values.map(x=>`<div class="day-item"><span style="color:${x.p.color};font-weight:1000">${esc(x.p.name)}</span><b>${x.v>0?(d.type==='exercise'?gymsibsWeight(x.v)+' kg':d.type==='swim'?x.v+' largos':Number(x.v).toLocaleString('es-ES')):'Sin registro'}</b></div>`).join('')}<div class="step-winner">${result}</div></div>`}).join('');
 const winner=ranking.length&&c.overall!=='tie'?`👑 ${ranking[0].name.toUpperCase()} GANA LA SEMANA`:'🤝 EMPATE EN CABEZA';
 return topHeader()+header('DUELO')+`<div class="duel-v11"><div class="duel-title">⚔️ ARENA GYMSIS ⚔️</div><div class="duel-sub">SEMANA CERRADA · ${range.start} → ${range.end}</div><div class="versus two-player">${scoreCards}</div><div class="lead ${c.overall==='tie'?'tie':''}">${winner}</div><div class="record">${c.details.length} PRUEBAS COMPARADAS · ${c.ties} EMPATES</div></div>${rows||'<p class="note">Todavía no hay datos comparables en la semana cerrada.</p>'}${historicalDuels()}`;
}
function totals(){const c=weeklyCompetition(weekRange());return Object.fromEntries(c.players.map(p=>[p.key,c.totals[p.key].wins]));}
function stepTotals(){const r=weekRange(),out=Object.fromEntries(gymsibsPlayers().map(p=>[p.key,0]));data.steps.filter(x=>x.date>=r.start&&x.date<=r.end).forEach(x=>{const k=gymsibsPlayer(x.user_id);if(k&&k in out)out[k]+=Number(x.steps)||0});return out}
function header(title,back=""){return `<div class="head"><button onclick="${back?`goBack('${back}')`:''}">${back?'←':''}</button><h1>${title}</h1><span>✦</span></div>`}
function topHeader(){const avatar=currentName()==='andrea'?'<img class="header-avatar" src="'+ANDREA_AVATAR+'">':'';return `<header><button class="top" onclick="more()">☰</button><button class="logo" onclick="go('home')"><img class="mini-logo" src="${MINI_LOGO}"></button><button class="user-chip" onclick="logout()">${avatar}${currentProfile?.name?.toUpperCase()||selectedLogin.toUpperCase()} · SALIR</button></header>`}
function render(){if(!currentUser){authScreen();return}if(loading){document.getElementById('app').innerHTML='<div class="auth-screen"><div class="auth-box"><h1 class="auth-title">CARGANDO...</h1></div></div>';return}const t=totals();let html='';if(screen==='home')html=home(t);if(screen==='exercises')html=exercises();if(screen==='workout')html=workout();if(screen==='progress')html=progress(t);if(screen==='duel')html=duel(t);if(screen==='achievements')html=achievements(t);if(screen==='calendar')html=calendar();if(screen==='steps')html=stepsScreen();if(screen==='swimming')html=swimmingScreen();if(screen==='pilates')html=pilatesScreen();document.getElementById('app').innerHTML=html;if(result)document.body.insertAdjacentHTML('beforeend',resultOverlay());if(screen==='progress')setTimeout(checkProgressImprovement,80)}
function swimTotals(){const r=weekRange(),out=Object.fromEntries(gymsibsPlayers().map(p=>[p.key,0]));data.swimming.filter(x=>x.date>=r.start&&x.date<=r.end).forEach(x=>{const k=gymsibsPlayer(x.user_id);if(k&&k in out)out[k]+=Math.max(0,Math.floor(Number(x.lengths)||0))});return out}
function distanceText(lengths){const meters=Math.max(0,Math.floor(Number(lengths)||0))*25;const km=meters/1000;return `${meters.toLocaleString('es-ES')} m · ${km.toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})} km`}
function home(t){const players=gymsibsPlayers(),last=data.records.find(r=>r.user_id===currentUser.id),st=stepTotals(),sw=swimTotals(),wr=weekRange();const latest=last?`<div class="card latest"><label>ÚLTIMO ENTRENAMIENTO</label><h3>${exerciseName(last.exercise_id)}</h3><div class="row"><span style="color:${currentProfile?.color||'#171019'}">${currentProfile?.name||currentName()}</span><b>${Number(last.weight)||0} kg × ${Number(last.reps)||0}</b></div><em>¡KACHOW!</em></div>`:'';const scores=players.map(p=>`<div class="player-score" style="border-color:${p.color}"><span style="color:${p.color}">${esc(p.name.toUpperCase())}</span><b>${t[p.key]||0}</b></div>`).join('');const stepRows=players.map(p=>`<b style="color:${p.color}">${esc(p.name)} · ${(st[p.key]||0).toLocaleString('es-ES')}</b>`).join('');const swimRows=players.map(p=>`<b style="color:${p.color}">${esc(p.name)} · ${(sw[p.key]||0).toLocaleString('es-ES')} largos</b>`).join('');return topHeader()+header('GymSis')+`<div class="card"><label>ESTA SEMANA · ${wr.start} → ${wr.end}</label><div class="score two-player">${scores}</div></div>${latest}<div class="steps-card"><small>👟 PASOS ESTA SEMANA</small><div class="player-metrics">${stepRows}</div></div><div class="steps-card swim-summary"><small>🏊 NATACIÓN ESTA SEMANA · PISCINA DE 25 M</small><div class="player-metrics">${swimRows}</div></div><div class="grid"><button class="action p" onclick="go('exercises')">🏋 ENTRENAR</button><button class="action bl" onclick="go('progress')">📈 PROGRESO</button><button class="action ye" onclick="go('duel')">⚡ DUELO</button><button class="action li" onclick="go('achievements')">🏆 LOGROS</button></div><button class="wide" onclick="go('steps')">👟 REGISTRAR PASOS</button><button class="wide" onclick="go('swimming')">🏊 REGISTRAR NATACIÓN</button><button class="wide" onclick="go('pilates')">🧘 REGISTRAR PILATES</button><button class="wide" onclick="go('calendar')">📅 CALENDARIO</button>`}
function exerciseGroups(){return ['Pierna','Pecho','Espalda','Hombros','Bíceps','Brazos','Core','Glúteos','Cardio','Otros']}
function exercises(){const available=data.exercises.filter(e=>e.active!==false);return topHeader()+header('ELIGE TU EJERCICIO','home')+`<div class="search">Buscar ejercicio... <b>⌕</b></div><div>${available.map(e=>`<div class="exercise"><button class="exercise-main" onclick="openEx('${e.id}')"><span>${e.icon}</span><div><b>${esc(e.name)}</b><small>${esc(e.group)}</small></div><strong>›</strong></button><div class="exercise-actions"><button class="exercise-edit" aria-label="Editar ejercicio" onclick="event.stopPropagation();editExercise('${e.id}')">✏️</button><button class="exercise-delete" aria-label="Eliminar ejercicio" onclick="event.stopPropagation();deleteExercise('${e.id}')">🗑️</button></div></div>`).join('')}</div>${adding?`<div class="addform"><input id="newex" placeholder="Nombre del ejercicio"><select id="newex-group">${exerciseGroups().map(g=>`<option value="${g}">${g}</option>`).join('')}</select><button onclick="addEx()">AÑADIR</button></div>`:`<button class="add" onclick="adding=true;render()">＋ AÑADIR EJERCICIO</button>`}`}
function workout(){const e=data.exercises.find(x=>x.id===exid&&x.active!==false)||data.exercises.find(x=>x.active!==false);if(!e)return header('SIN EJERCICIOS','home')+'<p class="note">No hay ejercicios disponibles.</p>';const last=data.records.find(r=>r.exercise_id===e.id&&r.user_id===currentUser.id),v={weight:gymsibsWeight(last?.weight),reps:gymsibsWeight(last?.reps)};return topHeader()+header(e.name.toUpperCase(),'exercises')+`<div class="panel ${currentName()==='ara'?'ara':'andrea'}"><div class="name">${currentProfile?.name?.toUpperCase()||currentName().toUpperCase()}</div>${metrics('me',v)}</div><div class="week-card"><h3>📅 DUELO CADA LUNES</h3><p class="note">Tú solo introduces tus datos. Cada lunes GymSis compara la semana anterior.</p></div><button class="register" onclick="register()">¡REGISTRAR! ⚡</button><p class="note">Tus datos se guardan en Supabase y estarán disponibles para Ara y Andrea.</p>`}
function metrics(prefix,v){return `<div class="metrics"><label class="metric"><small>PESO (KG)</small><input id="${prefix}w" type="number" step=".5" min="0" value="${v.weight}"><div><button onclick="step('${prefix}w',-1)">−</button><button onclick="step('${prefix}w',1)">+</button></div></label><label class="metric"><small>REPETICIONES</small><input id="${prefix}r" type="number" min="0" value="${v.reps}"><div><button onclick="step('${prefix}r',-1)">−</button><button onclick="step('${prefix}r',1)">+</button></div></label></div>`}
function progress(){
 const players=gymsibsPlayers();if(!players.some(p=>p.key===person))person=players[0]?.key||'ara';const selected=players.find(p=>p.key===person)||players[0];const mine=data.records.filter(x=>x.user_id===selected?.id);
 const rows=data.exercises.map(e=>{const r=mine.filter(x=>x.exercise_id===e.id).sort((a,b)=>`${a.date} ${a.created_at||''}`.localeCompare(`${b.date} ${b.created_at||''}`));if(!r.length)return null;const best=Math.max(...r.map(x=>gymsibsWeight(x.weight)));const latest=r[r.length-1];const prevBest=r.slice(0,-1).reduce((m,x)=>Math.max(m,gymsibsWeight(x.weight)),0);return {...e,best,prevBest,improved:gymsibsWeight(latest.weight)>prevBest&&prevBest>0&&gymsibsWeight(latest.weight)===best};}).filter(Boolean);
 const history=[...mine].sort((a,b)=>`${b.date} ${b.created_at||''}`.localeCompare(`${a.date} ${a.created_at||''}`)).slice(0,10);const c=weeklyCompetition(previousWeekRange());const wins=c.totals[selected?.key]?.wins||0;const maxBar=Math.max(50,...rows.map(x=>x.best||0));
 return topHeader()+header('MI PROGRESO')+`<div class="tabs profile-tabs">${players.map(p=>`<button class="${person===p.key?'selected-profile':''}" style="--profile-color:${p.color}" onclick="person='${p.key}';render()">${esc(p.name.toUpperCase())}</button>`).join('')}</div><div class="selected-player"><span style="color:${selected?.color}">${esc(selected?.name.toUpperCase()||'')}</span><small>DATOS PERSONALES</small></div><div class="stats"><div><b>${mine.length}</b><small>SESIONES</small></div><div><b>${wins}</b><small>PUNTOS ÚLT. SEM.</small></div><div><b>${rows.length}</b><small>EJERCICIOS</small></div></div><div class="card"><label>MEJORES MARCAS · ${esc(selected?.name.toUpperCase()||'')}</label>${rows.map(x=>{const basePct=Math.min(100,(x.prevBest||x.best)/maxBar*100),impPct=x.improved?Math.max(0,Math.min(100,x.best/maxBar*100-basePct)):0;return `<div class="progress-row ${x.improved?'record-improved':''}"><div class="bar-head"><span>${esc(x.name)} <small>${esc(x.group)}</small></span><b>${x.best} kg</b></div><div class="progress-bar-wrap"><i class="progress-bar-base" style="width:${basePct}%;background:${selected?.color}"></i>${impPct?`<i class="progress-bar-improvement" style="width:${impPct}%"></i>`:''}</div></div>`}).join('')||'<p class="note">Todavía no hay entrenamientos.</p>'}</div><div class="card"><label>HISTORIAL RECIENTE · ${esc(selected?.name.toUpperCase()||'')}</label>${history.map(r=>`<div class="history-item"><div><span>${r.date}</span><b>${esc(exerciseName(r.exercise_id))}</b><span>${gymsibsWeight(r.weight)} × ${gymsibsWeight(r.reps)}</span></div><div class="history-actions"><button class="edit-btn" onclick="editRecord('${r.id}')">✏️ EDITAR</button><button class="delete-btn" onclick="deleteRecord('${r.id}')">🗑 BORRAR</button></div></div>`).join('')||'<p class="note">Todavía no hay entrenamientos.</p>'}</div>`;
}
function checkProgressImprovement(){const selected=gymsibsPlayerByKey(person);if(!selected)return;const mine=data.records.filter(x=>x.user_id===selected.id);const keyParts=[];mine.forEach(r=>{const same=mine.filter(x=>x.exercise_id===r.exercise_id&&x.id!==r.id);const prev=Math.max(0,...same.map(x=>gymsibsWeight(x.weight)));if(prev>0&&gymsibsWeight(r.weight)>prev)keyParts.push(r.id)});const latest=keyParts[keyParts.length-1];if(latest){const key='gymsibs_confetti_'+latest;if(!localStorage.getItem(key)){localStorage.setItem(key,'1');launchConfetti()}}}
function launchConfetti(){const pieces=['var(--p)','var(--b)','var(--y)','var(--l)','var(--v)'];for(let i=0;i<55;i++){const el=document.createElement('span');el.className='confetti-piece';el.style.left=(Math.random()*100)+'vw';el.style.background=pieces[i%pieces.length];el.style.setProperty('--dx',((Math.random()-.5)*260)+'px');el.style.animationDelay=(Math.random()*.35)+'s';document.body.appendChild(el);setTimeout(()=>el.remove(),2200)}}
function historicalDuels(){
 const dates=[...data.records.map(x=>x.date),...data.steps.map(x=>x.date),...data.swimming.map(x=>x.date)].filter(Boolean).sort();if(!dates.length)return '';let cursor=mondayOf(new Date(dates[0]+'T00:00:00'));const current=mondayOf();const weeks=[];while(cursor<current){const range=weekRangeFor(cursor);const c=weeklyCompetition(range);if(c.details.length)weeks.push({range,c});cursor.setDate(cursor.getDate()+7)}weeks.reverse();return `<div class="duel-history"><h3>HISTORIAL DE DUELOS</h3><p class="history-intro">Resultados de semanas anteriores</p>${weeks.slice(0,20).map(({range,c})=>`<div class="duel-history-row"><div class="week">${range.start} → ${range.end}</div><div class="mini-info">${c.players.map(p=>`${esc(p.name)} ${c.totals[p.key].wins}`).join(' · ')}</div></div>`).join('')}</div>`;
}
function stepsScreen(){const me=currentUser.id,own=data.steps.filter(x=>x.user_id===me).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20),st=stepTotals(),date=stepsDateSelected||todayISO(),selected=data.steps.find(x=>x.user_id===me&&x.date===date);return topHeader()+header('PASOS','home')+`<div class="step-form"><label class="auth-field"><span>FECHA DEL REGISTRO</span><input id="stepDate" type="date" max="${todayISO()}" value="${date}" onchange="stepsDateSelected=this.value;const v=data.steps.find(x=>x.user_id===currentUser.id&&x.date===this.value);document.getElementById('stepsToday').value=Number(v?.steps)||0;document.querySelector('.step-date-label').textContent='PASOS DEL '+this.value"></label><label class="auth-field"><span class="step-date-label">PASOS DEL ${date}</span><input id="stepsToday" type="number" min="0" step="1" value="${Number(selected?.steps)||0}"></label><button onclick="saveSteps()">GUARDAR PASOS 👟</button></div><div class="card"><label>ESTA SEMANA</label>${gymsibsPlayers().map(p=>`<div class="week-total"><span class="who" style="color:${p.color}">${esc(p.name.toUpperCase())}</span><span class="num">${(st[p.key]||0).toLocaleString('es-ES')}</span></div>`).join('')}</div><div class="card"><label>MIS REGISTROS RECIENTES</label>${own.map(x=>`<div class="history-item"><div><span>${x.date}</span><b>${Number(x.steps).toLocaleString('es-ES')} pasos</b></div><div class="history-actions"><button class="delete-btn" onclick="deleteSteps('${x.id}')">🗑 BORRAR</button></div></div>`).join('')||'<p class="note">Todavía no has registrado pasos.</p>'}</div>`} function achievements(t){const my=data.records.filter(r=>r.user_id===currentUser.id),maxWeight=Math.max(0,...data.records.map(r=>gymsibsWeight(r.weight))),unique=new Set(my.map(r=>r.exercise_id)).size,w=weeklyScore();const items=[['💥','KACHOW!','Primer entrenamiento',my.length>=1],['⚡','MACHINE','5 registros',my.length>=5],['🔥','A POR EL SIGUIENTE','10 registros',my.length>=10],['🚀','MODO BESTIA','20 registros',my.length>=20],['💯','CENTURION','25 registros',my.length>=25],['🩷','NO HAY QUIEN LA PARE','Ara gana un ejercicio esta semana',(w.totals.ara?.wins||0)>=1],['💖','ARA-POCALYPSE','Ara gana 5 ejercicios semanales',(w.totals.ara?.wins||0)>=5],['👑','REINA DEL HIERRO','Ara gana 10 ejercicios semanales',(w.totals.ara?.wins||0)>=10],['💜','ANDREA POWER','Andrea gana un ejercicio esta semana',(w.totals.andrea?.wins||0)>=1],['💜','ANDREA SUPREMA','Andrea gana 5 ejercicios semanales',(w.totals.andrea?.wins||0)>=5],['🏆','REINA DEL DUELO','Andrea gana 10 ejercicios semanales',(w.totals.andrea?.wins||0)>=10],['🤝','COMEBACK KING','Primer empate semanal',w.ties>=1],['🎯','VERSÁTIL','Entrena 3 ejercicios distintos',unique>=3],['🧠','TODO CONTROLADO','Entrena 5 ejercicios distintos',unique>=5],['💪','50 CLUB','Alguien llega a 50 kg',maxWeight>=50],['🦾','100 CLUB','Alguien llega a 100 kg',maxWeight>=100],['☠️','MODO TITÁN','Alguien llega a 150 kg',maxWeight>=150],['📅','CONSTANCIA','Entrena en 3 días distintos',new Set(my.map(r=>r.date)).size>=3],['🌪️','SIN FRENOS','Entrena en 7 días distintos',new Set(my.map(r=>r.date)).size>=7],['🏋️','PRIMER RÉCORD','Supera 40 kg',maxWeight>=40]];return topHeader()+header('MIS LOGROS')+`<p class="note">Aquí se viene a entrenar... y a desbloquear cosas absurdamente satisfactorias 😎</p><div class="ach">${items.map(x=>`<div class="achievement ${x[3]?'on':''}"><div>${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small>${x[3]?'<span>DESBLOQUEADO</span>':''}</div>`).join('')}</div>`}
function calendar(){const year=calendarCursor.getFullYear(),month=calendarCursor.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7,names=['L','M','X','J','V','S','D'],me=currentUser.id;let cells=names.map(x=>`<b>${x}</b>`).join('');for(let i=0;i<offset;i++)cells+='<span></span>';for(let n=1;n<=days;n++){const ds=`${year}-${String(month+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;const has=data.records.some(r=>r.user_id===me&&r.date===ds)||data.steps.some(r=>r.user_id===me&&r.date===ds)||data.swimming.some(r=>r.user_id===me&&r.date===ds)||data.pilates.some(r=>r.user_id===me&&r.date===ds);const today=ds===todayISO();cells+=`<span class="calendar-day ${has?'has-data trained':''} ${today?'today':''}" onclick="showCalendarDay('${ds}')">${n}</span>`}const title=calendarCursor.toLocaleDateString('es-ES',{month:'long',year:'numeric'}).toUpperCase();return topHeader()+header('CALENDARIO')+`<div class="calendar-nav"><button onclick="changeCalendarMonth(-1)">‹</button><h2 class="month">${title}</h2><button onclick="changeCalendarMonth(1)">›</button></div><div class="calendar">${cells}</div><p class="note">Pulsa cualquier día para ver tus ejercicios, pasos, natación y Pilates.</p>`}
function changeCalendarMonth(delta){calendarCursor.setMonth(calendarCursor.getMonth()+delta);render()}
function showCalendarDay(ds){
 const mine=data.records.filter(r=>r.user_id===currentUser.id&&r.date===ds).sort((a,b)=>(a.created_at||'').localeCompare(b.created_at||''));
 const st=data.steps.find(x=>x.user_id===currentUser.id&&x.date===ds);
 const sw=data.swimming.find(x=>x.user_id===currentUser.id&&x.date===ds);
 const pl=data.pilates.find(x=>x.user_id===currentUser.id&&x.date===ds);
 const restKey=`gymsibs_rest_${currentUser.id}_${ds}`,isRest=localStorage.getItem(restKey)==='1';
 const dateLabel=new Date(ds+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 const totalReps=mine.reduce((n,r)=>n+gymsibsWeight(r.reps),0);
 const status=mine.length?'ENTRENAMIENTO REGISTRADO':isRest?'DÍA DE DESCANSO':'SIN ENTRENAMIENTO REGISTRADO';
 const workouts=mine.map(r=>`<div class="day-workout-row"><div class="day-workout-info"><b>🏋️ ${esc(exerciseName(r.exercise_id))}</b><span>${gymsibsWeight(r.weight)} kg · ${gymsibsWeight(r.reps)} repeticiones</span></div><div class="day-workout-actions"><button onclick="editRecord('${r.id}')">EDITAR</button><button class="delete-btn" onclick="deleteRecord('${r.id}')">BORRAR</button></div></div>`).join('')||'<p class="note">No hay ejercicios de fuerza registrados.</p>';
 const steps=st?`<div class="day-item"><span>👟 Pasos</span><b>${Number(st.steps).toLocaleString('es-ES')}</b></div>`:'<p class="note">No hay pasos registrados.</p>';
 const swim=sw?`<div class="day-item"><span>🏊 Natación</span><b>${Number(sw.lengths).toLocaleString('es-ES')} largos · ${distanceText(sw.lengths)}</b></div>`:'<p class="note">No hay natación registrada.</p>';
 const pilates=pl?`<div class="day-item"><span>🧘 Pilates</span><b>${pl.classes} clases</b></div>`:'<p class="note">No hay Pilates registrado.</p>';
 document.getElementById('dayModal')?.remove();
 document.body.insertAdjacentHTML('beforeend',`<div class="day-modal" id="dayModal" onclick="if(event.target===this)this.remove()"><div class="day-card">
 <div class="day-summary-head"><small>RESUMEN DEL DÍA</small><h2>${dateLabel}</h2><span class="day-status ${mine.length?'done':isRest?'rest':'empty'}">${status}</span><div class="day-summary-stats"><div><b>${mine.length}</b><small>ejercicios</small></div><div><b>${totalReps}</b><small>repeticiones</small></div><div><b>${st?Number(st.steps).toLocaleString('es-ES'):'—'}</b><small>pasos</small></div></div></div>
 <div class="day-section"><h3>🏋️ ENTRENAMIENTO DE FUERZA</h3>${workouts}<button class="day-add" onclick="openAddDayWorkout('${ds}')">＋ AÑADIR EJERCICIO</button></div>
 <div class="day-section"><h3>👟 PASOS</h3>${steps}<button class="day-add secondary-day-add" onclick="menuGo('steps')">VER / REGISTRAR PASOS</button></div>
 <div class="day-section"><h3>🏊 NATACIÓN</h3>${swim}<button class="day-add secondary-day-add" onclick="menuGo('swimming')">VER / REGISTRAR NATACIÓN</button></div>
 <div class="day-section"><h3>🧘 PILATES</h3>${pilates}<button class="day-add secondary-day-add" onclick="menuGo('pilates')">VER / REGISTRAR PILATES</button></div>
 <div class="day-rest-actions">${isRest?`<button class="secondary" onclick="setDayRest('${ds}',false)">QUITAR DÍA DE DESCANSO</button>`:`<button class="secondary" onclick="setDayRest('${ds}',true)">MARCAR COMO DESCANSO</button>`}</div>
 <p class="day-hint">${mine.length||st||sw||pl?'Revisa los registros por si falta alguna actividad.':'No hay actividad guardada. Si entrenaste, añádela; si descansaste, marca el día como descanso.'}</p>
 <button class="day-close" onclick="document.getElementById('dayModal')?.remove()">CERRAR</button></div></div>`);
}
function setDayRest(ds,value){
 const key=`gymsibs_rest_${currentUser.id}_${ds}`;
 if(value)localStorage.setItem(key,'1');else localStorage.removeItem(key);
 showCalendarDay(ds);
}
function openAddDayWorkout(ds){
 const options=data.exercises.filter(e=>e.active!==false).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');
 document.getElementById('dayAddModal')?.remove();
 document.body.insertAdjacentHTML('beforeend',`<div class="edit-modal" id="dayAddModal"><div class="edit-card"><h2>AÑADIR ENTRENAMIENTO</h2><p>Registra un ejercicio para el ${ds}</p><label>EJERCICIO<select id="day-add-exercise">${options}</select></label><div class="edit-grid"><label>PESO (KG)<input id="day-add-weight" type="number" min="0" step="0.5" value="20"></label><label>REPETICIONES<input id="day-add-reps" type="number" min="1" value="10"></label></div><label>FECHA<input id="day-add-date" type="date" value="${ds}" max="${todayISO()}"></label><div class="edit-actions"><button class="secondary" onclick="document.getElementById('dayAddModal')?.remove()">CANCELAR</button><button onclick="saveDayWorkout()">GUARDAR</button></div></div></div>`);
}
async function saveDayWorkout(){
 const exercise_id=document.getElementById('day-add-exercise')?.value,date=document.getElementById('day-add-date')?.value;
 const weight=gymsibsNumber(document.getElementById('day-add-weight')?.value),reps=gymsibsNumber(document.getElementById('day-add-reps')?.value);
 if(!exercise_id||!date||date>todayISO()||weight<=0||reps<=0){alert('Comprueba el ejercicio, la fecha, el peso y las repeticiones.');return}
 const {data:row,error}=await sb.from('workouts').insert({user_id:currentUser.id,exercise_id,date,weight,reps}).select('id,user_id,exercise_id,date,weight,reps,created_at').single();
 if(error){alert('No se ha podido guardar el entrenamiento.');console.error(error);return}
 data.records.unshift(row);document.getElementById('dayAddModal')?.remove();showCalendarDay(date);showToast('ENTRENAMIENTO AÑADIDO ✓');
}
function resultOverlay(){return ''; }
async function go(s){screen=s;result=null;navIndex++;history.pushState({gymsibs:true,screen,index:navIndex},'',location.href);render();if(s==='duel'){try{await loadData();render();}catch(err){console.error('No se pudo actualizar el duelo:',err);showToast('No se han podido actualizar los datos del duelo');}}}
function goBack(fallback='home'){if(navIndex>0){history.back()}else{screen=fallback;render()}}
window.addEventListener('popstate',e=>{if(e.state?.gymsibs){navIndex=Math.max(0,Number(e.state.index)||0);screen=e.state.screen||'home';result=null;render()}else if(currentUser){navIndex=0;screen='home';result=null;render()}});
function openEx(id){exid=id;screen='workout';navIndex++;history.pushState({gymsibs:true,screen:'workout',index:navIndex},'',location.href);render()}function step(id,n){let x=document.getElementById(id);x.value=Math.max(0,(Number(x.value)||0)+n)}
async function register(){
 const weight=Number(document.getElementById('mew')?.value)||0;
 const reps=Number(document.getElementById('mer')?.value)||0;
 if(weight<=0||reps<=0){alert('Introduce peso y repeticiones.');return}
 const btn=document.querySelector('.register');
 if(btn){btn.disabled=true;btn.textContent='GUARDANDO...'}
 const {data:row,error}=await sb.from('workouts').insert({user_id:currentUser.id,exercise_id:exid,date:todayISO(),weight,reps}).select('id,user_id,exercise_id,date,weight,reps,created_at').single();
 if(error){if(btn){btn.disabled=false;btn.textContent='¡REGISTRAR! ⚡'}alert('No se ha podido guardar el entrenamiento.');console.error(error);return}
 data.records.unshift(row);
 result=null;
 document.getElementById('result')?.remove();
 screen='exercises';
 render();
 showToast('ENTRENAMIENTO GUARDADO ✓');
}
async function editRecord(id){
 const r=data.records.find(x=>x.id===id&&x.user_id===currentUser.id);if(!r)return;
 document.getElementById('editModal')?.remove();
 const modal=document.createElement('div');modal.className='edit-modal';modal.id='editModal';
 modal.innerHTML=`<div class="edit-card"><h2>EDITAR ENTRENAMIENTO</h2><p style="font-weight:900;margin-top:0">${esc(exerciseName(r.exercise_id))}</p><div class="edit-grid"><label>PESO (KG)<input id="edit-w" type="number" step="0.5" min="0" value="${gymsibsWeight(r.weight)}"></label><label>REPETICIONES<input id="edit-r" type="number" min="1" value="${gymsibsWeight(r.reps)}"></label></div><label>FECHA<input id="edit-date" type="date" max="${todayISO()}" value="${r.date}"></label><div class="edit-actions"><button class="secondary" onclick="document.getElementById('editModal')?.remove()">CANCELAR</button><button onclick="saveEditedRecord('${id}')">GUARDAR CAMBIOS</button></div></div>`;
 document.body.appendChild(modal);
}
async function saveEditedRecord(id){
 const weight=gymsibsNumber(document.getElementById('edit-w')?.value),reps=gymsibsNumber(document.getElementById('edit-r')?.value),date=document.getElementById('edit-date')?.value;
 if(weight<=0||reps<=0||!date||date>todayISO()){alert('Introduce valores y una fecha válidos.');return}
 const {data:row,error}=await sb.from('workouts').update({weight,reps,date}).eq('id',id).eq('user_id',currentUser.id).select('id,user_id,exercise_id,date,weight,reps,created_at').single();
 if(error){alert('No se ha podido guardar.');console.error(error);return}
 const i=data.records.findIndex(x=>x.id===id);if(i>=0)data.records[i]=row;
 document.getElementById('editModal')?.remove();document.getElementById('dayModal')?.remove();showCalendarDay(row.date);showToast('CAMBIOS GUARDADOS ✓');
}
async function deleteRecord(id){
 const r=data.records.find(x=>x.id===id&&x.user_id===currentUser.id);if(!r)return;
 if(!confirm(`¿Borrar el entrenamiento de ${exerciseName(r.exercise_id)} del ${r.date}?\n\nEsta acción no se puede deshacer.`))return;
 const {error}=await sb.from('workouts').delete().eq('id',id).eq('user_id',currentUser.id);
 if(error){alert('No se ha podido borrar.');console.error(error);return}
 data.records=data.records.filter(x=>x.id!==id);const refreshDay=document.getElementById('dayModal')?r.date:null;render();if(refreshDay)showCalendarDay(refreshDay);showToast('ENTRENAMIENTO BORRADO ✓');
}
async function saveSteps(){
 const steps=Math.max(0,Math.floor(Number(document.getElementById('stepsToday')?.value)||0)),date=document.getElementById('stepDate')?.value||todayISO();if(!date||date>todayISO()){alert('Selecciona una fecha válida, hoy o anterior.');return}stepsDateSelected=date;
 const {data:row,error}=await sb.from('steps').upsert({user_id:currentUser.id,date,steps},{onConflict:'user_id,date'}).select('id,user_id,date,steps,created_at').single();
 if(error){alert('No se han podido guardar los pasos.');console.error(error);return}
 data.steps=data.steps.filter(x=>!(x.user_id===currentUser.id&&x.date===date));data.steps.unshift(row);
 if(steps>8000){const {error:xpError}=await sb.from('xp_transactions').insert({user_id:currentUser.id,amount:5,transaction_type:'step_goal_bonus',description:'Objetivo diario: más de 8.000 pasos · '+date,reference_id:row.id,award_key:'steps-over-8000:'+currentUser.id+':'+date});if(xpError&&!String(xpError.message||'').toLowerCase().includes('duplicate'))console.warn('XP pasos',xpError.message)}
 await v21Load();render();showToast(steps>8000?'PASOS GUARDADOS · +5 XP':'PASOS GUARDADOS ✓');
}
async function deleteSteps(id){
 if(!confirm('¿Borrar este registro de pasos?'))return;
 const {error}=await sb.from('steps').delete().eq('id',id).eq('user_id',currentUser.id);
 if(error){alert('No se ha podido borrar.');console.error(error);return}
 data.steps=data.steps.filter(x=>x.id!==id);render();showToast('PASOS BORRADOS ✓');
}
async function addEx(){const n=document.getElementById('newex')?.value.trim();const group=document.getElementById('newex-group')?.value||'Otros';if(!n)return;const {data:row,error}=await sb.from('exercises').insert({name:n,group_name:group,icon:'🏋️'}).select('id,name,group_name,icon,active').single();if(error){alert('No se ha podido añadir el ejercicio.');console.error(error);return}data.exercises.push({id:row.id,name:row.name,group:row.group_name||'Otros',icon:row.icon||'🏋️'});adding=false;render();showToast('EJERCICIO AÑADIDO ✓')}
async function deleteExercise(id){
 const e=data.exercises.find(x=>x.id===id);if(!e)return;
 const used=data.records.some(r=>r.exercise_id===id);
 const message=used?`¿Eliminar «${e.name}» del catálogo?\n\nSe ocultará para futuros entrenamientos, pero se conservará su historial (${data.records.filter(r=>r.exercise_id===id).length} registros).`:`¿Eliminar «${e.name}» del catálogo?\n\nSe ocultará y no podrás seleccionarlo en nuevos entrenamientos.`;
 if(!confirm(message))return;
 const {data:row,error}=await sb.from('exercises').update({active:false}).eq('id',id).select('id,active').single();
 if(error){alert('No se ha podido eliminar el ejercicio. Comprueba los permisos de actualización de Supabase en la tabla exercises.');console.error(error);return}
 e.active=false;
 if(exid===id)exid=null;
 render();showToast('EJERCICIO ELIMINADO DEL CATÁLOGO ✓');
}
function editExercise(id){const e=data.exercises.find(x=>x.id===id);if(!e)return;const modal=document.createElement('div');modal.className='edit-modal';modal.id='editExerciseModal';modal.innerHTML=`<div class="edit-card edit-exercise-card"><h2>EDITAR EJERCICIO</h2><label>NOMBRE<input id="exercise-edit-name" value="${esc(e.name)}"></label><label>TIPO<select id="exercise-edit-group">${exerciseGroups().map(g=>`<option value="${g}" ${e.group===g?'selected':''}>${g}</option>`).join('')}</select></label><div class="edit-actions"><button class="secondary" onclick="document.getElementById('editExerciseModal')?.remove()">CANCELAR</button><button onclick="saveExerciseEdit('${id}')">GUARDAR</button></div></div>`;document.body.appendChild(modal)}
