async function savePilates(){const classes=Math.max(0,Math.floor(Number(document.getElementById('pilatesToday')?.value)||0)),date=todayISO();if(classes<=0){alert('Introduce al menos una clase.');return}const {data:row,error}=await sb.from('pilates').upsert({user_id:currentUser.id,date,classes},{onConflict:'user_id,date'}).select('id,user_id,date,classes,created_at').single();if(error){alert('No se ha podido guardar Pilates. Comprueba que has creado la tabla pilates con el SQL incluido.');console.error(error);return}data.pilates=data.pilates.filter(x=>!(x.user_id===currentUser.id&&x.date===date));data.pilates.unshift(row);render();showToast('PILATES GUARDADO ✓')}
