function mondayDuelOverlay(c){
 const existing=document.getElementById('mondayDuel');if(existing)existing.remove();const players=c.players;
 const items=c.details.map(d=>{const active=d.active.map(k=>players.find(p=>p.key===k)).filter(Boolean);const max=Math.max(...active.map(p=>Number(d.values[p.key])||0));const winners=active.filter(p=>Number(d.values[p.key])===max);return `<div class="monday-slide"><div class="slide-kicker">${d.icon} ${esc(d.name)}</div><div class="slide-values" style="grid-template-columns:repeat(${active.length},1fr)">${active.map(p=>`<div class="slide-player" style="background:${p.color}33"><small>${esc(p.name.toUpperCase())}</small><b>${d.type==='exercise'?gymsibsWeight(d.values[p.key])+' kg':d.type==='swim'?d.values[p.key]+' largos':Number(d.values[p.key]).toLocaleString('es-ES')}</b></div>`).join('')}</div><div class="slide-winner ${winners.length>1?'tie':''}">${winners.length===1?'🏆 ¡GANA '+esc(winners[0].name.toUpperCase())+'!':'🤝 ¡EMPATE!'}</div></div>`}).join('');
 const ranking=[...players].sort((a,b)=>c.totals[b.key].wins-c.totals[a.key].wins);const leader=ranking[0];const tied=ranking.length>1&&c.totals[leader.key].wins===c.totals[ranking[1].key].wins;const overall=tied?'EMPATE':leader.name.toUpperCase();
 document.body.insertAdjacentHTML('beforeend',`<div class="monday-overlay" id="mondayDuel" onclick="if(event.target===this)this.remove()"><div class="monday-card"><button class="monday-close" aria-label="Cerrar duelo semanal" title="Cerrar" onclick="document.getElementById('mondayDuel')?.remove()">×</button><div class="monday-top">⚔️ RESULTADOS DE LA SEMANA ⚔️</div><div class="monday-week">${c.range.start} → ${c.range.end}</div><div id="mondaySlides">${items}</div><div class="monday-final" id="mondayFinal"><div>👑 GANADOR DE LA SEMANA 👑</div><strong>${overall}</strong><span>${players.map(p=>`${esc(p.name)}: ${c.totals[p.key].wins}`).join(' · ')}</span><button onclick="document.getElementById('mondayDuel')?.remove()">¡KACHOW! CONTINUAR</button></div></div></div>`);
 let i=0,slides=[...document.querySelectorAll('#mondaySlides .monday-slide')];slides.forEach(x=>x.style.display='none');const next=()=>{if(i<slides.length){slides[i].style.display='block';slides[i].classList.add('pop-in');i++;setTimeout(next,1700)}else{document.getElementById('mondayFinal').classList.add('pop-in');}};next();
}
async function maybeShowMondayDuel(){if(!isMonday())return;const prev=previousWeekRange(),key='gymsibs_monday_duel_'+prev.start;if(localStorage.getItem(key)=== '1')return;const c=weeklyCompetition(prev);if(!c.details.length)return;localStorage.setItem(key,'1');setTimeout(()=>mondayDuelOverlay(c),700);}

